html:
{%- set cur = frappe.db.get_value("Currency", doc.currency, "symbol") or "ر.س" -%}
{%- set comp = frappe.get_doc("Company", doc.company) -%}
{%- set vat = comp.tax_id or "" -%}
{%- set phone = comp.phone_no or "" -%}
{%- set site_url = comp.website or "" -%}
{%- set has_serials = doc.items | selectattr("serial_no") | list | length > 0 -%}
{%- set grand_total_str = "%.2f" | format(doc.grand_total or 0) -%}
{%- set vat_amount = 0 -%}
{%- for t in doc.taxes -%}{%- if t.charge_type and t.tax_amount -%}{%- set vat_amount = vat_amount + t.tax_amount -%}{%- endif -%}{%- endfor -%}
{%- set vat_amount_str = "%.2f" | format(vat_amount) -%}
{%- set inv_dt = doc.posting_date | string + "T" + (doc.posting_time | string or "00:00:00") -%}
{%- set zatca_qr = generate_zatca_qr_dataurl(comp.company_name or doc.company, vat or "", inv_dt, grand_total_str, vat_amount_str) if vat else "" -%}
{%- set company_logo = comp.company_logo or "" -%}
{%- set company_display_name = comp.company_name or doc.company -%}

<style>
  @page { size: 80mm auto; margin: 0; }
  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: 'DejaVu Sans', 'Noto Sans Arabic', Arial, sans-serif;
    width: 80mm;
    max-width: 80mm;
    margin: 0 auto;
    padding: 7px 9px 14px;
    font-size: 10.5px;
    line-height: 1.5;
    color: #111;
  }

  /* ─── HEADER ─── */
  .hdr { text-align: center; padding-bottom: 8px; }
  .hdr-rule {
    border: none;
    border-top: 2.5px solid #111;
    margin: 5px 0 4px;
  }
  .hdr-rule-thin {
    border: none;
    border-top: 1px solid #111;
    margin: 3px 0;
  }
  .brand-en {
    font-size: 20px;
    font-weight: 900;
    letter-spacing: 3px;
    line-height: 1.2;
  }
  .brand-ar {
    font-size: 12px;
    font-weight: bold;
    letter-spacing: 0.5px;
    margin-top: 1px;
  }
  .brand-tagline {
    font-size: 8.5px;
    color: #555;
    letter-spacing: 0.5px;
    margin-top: 3px;
  }
  .inv-type-badge {
    display: inline-block;
    border: 1.5px solid #111;
    padding: 2px 18px;
    font-size: 10px;
    font-weight: bold;
    letter-spacing: 1.5px;
    margin-top: 7px;
  }

  /* ─── DIVIDERS ─── */
  .div-double { border-top: 3px double #111; margin: 8px 0; }
  .div-solid  { border-top: 1.5px solid #111; margin: 7px 0; }
  .div-dash   { border-top: 1px dashed #666; margin: 6px 0; }
  .div-dot    { border-top: 1px dotted #aaa; margin: 5px 0; }

  /* ─── INFO ROWS ─── */
  .info-section { font-size: 9.5px; margin: 5px 0; }
  .irow {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    padding: 1.5px 0;
  }
  .irow-lbl { color: #555; white-space: nowrap; margin-left: 6px; }
  .irow-val { font-weight: 700; text-align: left; word-break: break-all; }

  /* ─── COLUMN HEADERS ─── */
  .col-hdr {
    display: flex;
    justify-content: space-between;
    font-size: 8.5px;
    color: #666;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    padding: 3px 0 2px;
    border-bottom: 1px solid #ccc;
    margin-bottom: 7px;
  }

  /* ─── ITEM ROWS ─── */
  .item-wrap { margin-bottom: 10px; }
  .item-name {
    font-size: 11px;
    font-weight: 700;
    line-height: 1.35;
    margin-bottom: 2px;
  }
  .free-pill {
    display: inline-block;
    background: #111;
    color: #fff;
    font-size: 7.5px;
    padding: 1px 6px;
    border-radius: 9px;
    letter-spacing: 0.5px;
    vertical-align: middle;
    margin-right: 3px;
  }
  .item-line2 {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 10px;
    color: #333;
  }
  .item-qty-price { color: #555; }
  .item-amount    { font-weight: 700; }
  .disc-chip {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    background: #f2f2f2;
    border: 1px solid #ddd;
    border-radius: 3px;
    padding: 1px 6px;
    font-size: 9px;
    margin-top: 3px;
    color: #333;
  }
  .disc-arrow { font-size: 8px; }

  /* ─── SERIAL BOX ─── */
  .serial-wrap {
    margin-top: 5px;
    border: 1.5px solid #111;
    border-radius: 2px;
    overflow: hidden;
  }
  .serial-head {
    background: #111;
    color: #fff;
    font-size: 8px;
    font-weight: 700;
    letter-spacing: 1px;
    padding: 2px 7px;
    display: flex;
    justify-content: space-between;
  }
  .serial-body {
    padding: 4px 7px;
    background: #fafafa;
  }
  .imei-num {
    font-family: 'Courier New', Courier, monospace;
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 1.5px;
    color: #000;
  }
  .imei-hint { font-size: 7.5px; color: #888; margin-top: 1px; }

  /* ─── TOTALS ─── */
  .totals-section { margin: 5px 0 8px; }
  .tot-line {
    display: flex;
    justify-content: space-between;
    font-size: 10px;
    padding: 2px 0;
  }
  .tot-lbl { color: #555; }
  .disc-amount { color: #111; font-weight: 700; }

  /* THE BIG TOTAL */
  .total-box {
    border: 2px solid #111;
    margin: 9px 0 6px;
    padding: 8px 12px;
    text-align: center;
    position: relative;
  }
  .total-box-lbl {
    font-size: 9px;
    color: #555;
    letter-spacing: 2px;
    text-transform: uppercase;
    margin-bottom: 4px;
  }
  .total-box-lbl-ar {
    font-size: 11px;
    font-weight: 700;
    margin-bottom: 5px;
  }
  .total-box-amount {
    font-size: 24px;
    font-weight: 900;
    letter-spacing: 1px;
    line-height: 1;
  }
  .total-box-cur {
    font-size: 13px;
    font-weight: 700;
    margin-right: 2px;
  }

  /* ─── PAYMENTS ─── */
  .pay-section { margin-top: 8px; }
  .pay-title {
    font-size: 9px;
    letter-spacing: 1.5px;
    color: #555;
    text-transform: uppercase;
    margin-bottom: 5px;
  }
  .pay-card {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border: 1px solid #ddd;
    border-radius: 3px;
    padding: 4px 8px;
    margin-bottom: 3px;
    font-size: 10.5px;
  }
  .pay-icon-text { margin-right: 5px; font-size: 10px; }
  .pay-method-name { font-weight: 600; }
  .pay-amount { font-weight: 700; }
  .change-line {
    display: flex;
    justify-content: space-between;
    font-size: 9.5px;
    color: #555;
    padding: 3px 2px;
  }
  .balance-box {
    border: 2px solid #111;
    background: #f5f5f5;
    padding: 6px 10px;
    display: flex;
    justify-content: space-between;
    font-weight: 700;
    font-size: 12px;
    margin-top: 6px;
    border-radius: 2px;
  }

  /* ─── WARRANTY ─── */
  .warranty-block {
    border: 1px dashed #888;
    border-radius: 3px;
    padding: 6px 8px;
    margin: 9px 0 5px;
    text-align: center;
    font-size: 9px;
    color: #333;
    line-height: 1.7;
  }
  .warranty-icon { font-size: 12px; }
  .warranty-title { font-weight: 700; font-size: 10px; margin-bottom: 2px; }

  /* ─── FOOTER ─── */
  .footer { text-align: center; margin-top: 10px; }
  .footer-thanks-ar { font-size: 14px; font-weight: 900; margin-bottom: 2px; }
  .footer-thanks-en { font-size: 9px; color: #555; letter-spacing: 0.5px; }
  .stars { font-size: 12px; letter-spacing: 3px; margin: 7px 0; }
  .footer-contact { font-size: 8.5px; color: #666; margin-top: 4px; }
  .receipt-id {
    font-size: 7.5px;
    color: #bbb;
    margin-top: 8px;
    letter-spacing: 0.5px;
  }

  /* ─── LOGO ─── */
  .logo-wrap {
    text-align: center;
    margin-bottom: 5px;
  }
  .company-logo {
    max-width: 120px;
    max-height: 60px;
    object-fit: contain;
    display: block;
    margin: 0 auto 4px;
  }

  /* ─── ZATCA QR ─── */
  .zatca-qr {
    text-align: center;
    margin: 10px 0 4px;
    padding: 8px 4px;
    border: 1px solid #ddd;
    border-radius: 4px;
    background: #fafafa;
  }
  .zatca-qr img {
    width: 110px;
    height: 110px;
    display: block;
    margin: 0 auto 4px;
  }
  .zatca-label {
    font-size: 7px;
    color: #777;
    letter-spacing: 0.3px;
  }
  .zatca-badge {
    font-size: 8px;
    font-weight: 700;
    color: #064e3b;
    letter-spacing: 0.5px;
    margin-bottom: 3px;
  }

  @media print {
    body { padding: 4mm 5mm 10mm; }
  }
</style>

<!-- ══════════════════════════════════════════ -->
<!--                   HEADER                   -->
<!-- ══════════════════════════════════════════ -->
<div class="hdr">
  <hr class="hdr-rule">

  {%- if company_logo -%}
  <div class="logo-wrap">
    <img class="company-logo"
         src="{{ company_logo }}"
         alt="{{ company_display_name }}" />
  </div>
  {%- else -%}
  <div class="brand-en">{{ company_display_name | upper }}</div>
  {%- endif -%}

  <hr class="hdr-rule-thin">

  {%- if phone or site_url -%}
  <div class="brand-tagline">
    {%- if phone -%}☎ {{ phone }}{%- endif -%}
    {%- if phone and site_url -%} · {%- endif -%}
    {%- if site_url -%}{{ site_url }}{%- endif -%}
  </div>
  {%- endif -%}

  <div class="inv-type-badge">فاتورة ضريبية مبسطة · TAX INVOICE</div>
  <hr class="hdr-rule">
</div>

<!-- ══════════════════════════════════════════ -->
<!--              INVOICE META                  -->
<!-- ══════════════════════════════════════════ -->
<div class="info-section">
  <div class="irow">
    <span class="irow-lbl">رقم الفاتورة</span>
    <span class="irow-val" style="font-size:9px;">{{ doc.name }}</span>
  </div>
  <div class="irow">
    <span class="irow-lbl">التاريخ / Date</span>
    <span class="irow-val">{{ doc.posting_date }}</span>
  </div>
  <div class="irow">
    <span class="irow-lbl">الوقت / Time</span>
    <span class="irow-val">{{ (doc.posting_time|string).split('.')[0] if doc.posting_time else '─' }}</span>
  </div>
  {%- if doc.customer_name and doc.customer_name not in ['زبون','Walk-In Customer','Guest'] -%}
  <div class="irow">
    <span class="irow-lbl">العميل</span>
    <span class="irow-val">{{ doc.customer_name }}</span>
  </div>
  {%- endif -%}
  {%- if vat -%}
  <div class="irow">
    <span class="irow-lbl">الرقم الضريبي</span>
    <span class="irow-val" style="font-size:9px;letter-spacing:0.5px;">{{ vat }}</span>
  </div>
  {%- endif -%}
</div>

<hr class="div-double">

<!-- ══════════════════════════════════════════ -->
<!--                  ITEMS                     -->
<!-- ══════════════════════════════════════════ -->
<div class="col-hdr">
  <span>الصنف · ITEM</span>
  <span>المبلغ · AMOUNT</span>
</div>

{%- for item in doc.items -%}
<div class="item-wrap">

  <!-- Item Name -->
  <div class="item-name">
    {%- if item.is_free_item -%}<span class="free-pill">مجاني</span>{%- endif -%}
    {{ item.item_name }}
  </div>

  <!-- Qty × Price = Amount -->
  <div class="item-line2">
    {%- if item.is_free_item -%}
      <span class="item-qty-price">{{ "%.0f"|format(item.qty) }} × مجاني</span>
      <span class="item-amount" style="color:#111;">0.00 {{ cur }}</span>
    {%- else -%}
      <span class="item-qty-price">{{ "%.0f"|format(item.qty) }} × {{ "%.2f"|format(item.price_list_rate or item.rate) }} {{ cur }}</span>
      <span class="item-amount">{{ "%.2f"|format(item.qty * (item.price_list_rate or item.rate)) }} {{ cur }}</span>
    {%- endif -%}
  </div>

  <!-- Discount chip -->
  {%- if (item.discount_percentage and item.discount_percentage > 0) or (item.discount_amount and item.discount_amount > 0) -%}
  <div>
    <span class="disc-chip">
      <span class="disc-arrow">▼</span>
      خصم
      {%- if item.discount_percentage and item.discount_percentage > 0 -%}
        {{ " %.0f"|format(item.discount_percentage) }}%
      {%- endif -%}
      &nbsp;−&nbsp;{{ "%.2f"|format(item.discount_amount or 0) }} {{ cur }}
    </span>
  </div>
  {%- endif -%}

  <!-- Serial / IMEI box -->
  {%- if item.serial_no -%}
  <div class="serial-wrap">
    <div class="serial-head">
      <span>◈ IMEI / رقم التسلسل</span>
      <span>ضمان · WARRANTY</span>
    </div>
    <div class="serial-body">
      {%- for sn in item.serial_no.split('\n') -%}
        {%- if sn.strip() -%}
        <div class="imei-num">{{ sn.strip() }}</div>
        {%- endif -%}
      {%- endfor -%}
      <div class="imei-hint">احتفظ بالفاتورة لتفعيل الضمان</div>
    </div>
  </div>
  {%- endif -%}

</div>
{%- if not loop.last -%}<hr class="div-dot">{%- endif -%}
{%- endfor -%}

<hr class="div-double">

<!-- ══════════════════════════════════════════ -->
<!--                  TOTALS                    -->
<!-- ══════════════════════════════════════════ -->
<div class="totals-section">
  {%- if doc.total_taxes_and_charges and doc.total_taxes_and_charges > 0 -%}
  <div class="tot-line">
    <span class="tot-lbl">الإجمالي قبل الضريبة</span>
    <span>{{ "%.2f"|format(doc.grand_total - doc.total_taxes_and_charges) }} {{ cur }}</span>
  </div>
  <div class="tot-line">
    <span class="tot-lbl">ضريبة القيمة المضافة 15%</span>
    <span>{{ "%.2f"|format(doc.total_taxes_and_charges) }} {{ cur }}</span>
  </div>
  {%- endif -%}
  {%- if doc.discount_amount and doc.discount_amount > 0 -%}
  <div class="tot-line">
    <span class="tot-lbl">خصم إضافي</span>
    <span class="disc-amount">− {{ "%.2f"|format(doc.discount_amount) }} {{ cur }}</span>
  </div>
  {%- endif -%}
</div>

<!-- BIG TOTAL -->
<div class="total-box">
  <div class="total-box-lbl-ar">الإجمالي المستحق</div>
  <div class="total-box-lbl">TOTAL DUE</div>
  <div class="total-box-amount">
    <span class="total-box-cur">{{ cur }}</span>{{ "%.2f"|format(doc.grand_total) }}
  </div>
</div>

<!-- ══════════════════════════════════════════ -->
<!--                PAYMENTS                    -->
<!-- ══════════════════════════════════════════ -->
{%- if doc.payments -%}
<div class="pay-section">
  <div class="pay-title">▸ طريقة الدفع · PAYMENT</div>
  {%- for p in doc.payments -%}
  {%- if p.amount and p.amount > 0 -%}
  <div class="pay-card">
    <div>
      <span class="pay-icon-text">{%- if 'نقد' in p.mode_of_payment -%}◎
      {%- elif 'Apple Pay' in p.mode_of_payment -%}
      {%- elif 'STC' in p.mode_of_payment -%}◉
      {%- elif 'مدي' in p.mode_of_payment or 'Mada' in p.mode_of_payment -%}▣
      {%- elif 'بطاقة' in p.mode_of_payment or 'ائتمان' in p.mode_of_payment -%}▤
      {%- elif 'تحويل' in p.mode_of_payment or 'بنك' in p.mode_of_payment -%}⊡
      {%- elif 'تابي' in p.mode_of_payment or 'Tabby' in p.mode_of_payment -%}◇
      {%- elif 'تمارا' in p.mode_of_payment or 'Tamara' in p.mode_of_payment -%}◆
      {%- else -%}◈{%- endif -%}</span>
      <span class="pay-method-name">{{ p.mode_of_payment }}</span>
    </div>
    <span class="pay-amount">{{ "%.2f"|format(p.amount) }} {{ cur }}</span>
  </div>
  {%- endif -%}
  {%- endfor -%}

  {%- if doc.change_amount and doc.change_amount > 0 -%}
  <div class="change-line">
    <span>المبلغ المدفوع · Paid</span>
    <span>{{ "%.2f"|format(doc.paid_amount or 0) }} {{ cur }}</span>
  </div>
  <div class="change-line" style="font-weight:700;color:#111;font-size:11px;">
    <span>الباقي · Change</span>
    <span>{{ "%.2f"|format(doc.change_amount) }} {{ cur }}</span>
  </div>
  {%- endif -%}

  {%- if doc.outstanding_amount and doc.outstanding_amount > 0 -%}
  <div class="balance-box">
    <span>المبلغ المتبقي · Balance Due</span>
    <span>{{ "%.2f"|format(doc.outstanding_amount) }} {{ cur }}</span>
  </div>
  {%- endif -%}
</div>
{%- endif -%}

<!-- ══════════════════════════════════════════ -->
<!--                WARRANTY                    -->
<!-- ══════════════════════════════════════════ -->
{%- if has_serials -%}
<div class="warranty-block">
  <div class="warranty-icon">★</div>
  <div class="warranty-title">ضمان المنتج · Product Warranty</div>
  <div>سنة كاملة من تاريخ الشراء</div>
  <div>One year from purchase date</div>
  <div style="margin-top:3px;font-size:8.5px;color:#555;">الفاتورة وثيقة الضمان — احتفظ بها</div>
</div>
{%- endif -%}

<!-- ══════════════════════════════════════════ -->
<!--                 FOOTER                     -->
<!-- ══════════════════════════════════════════ -->
{%- if zatca_qr -%}
<div class="zatca-qr">
  <div class="zatca-badge">◈ فاتورة ضريبية إلكترونية · ZATCA e-Invoice</div>
  <img src="{{ zatca_qr }}" alt="ZATCA QR Code" />
  <div class="zatca-label">امسح رمز QR للتحقق من الفاتورة الضريبية</div>
  <div class="zatca-label">Scan QR to verify tax invoice · رقم ضريبي: {{ vat }}</div>
</div>
{%- endif -%}
<div class="footer">
  <hr class="div-dash">
  <div class="footer-thanks-ar">شكراً لتسوّقك معنا</div>
  <div class="footer-thanks-en">Thank you for your visit!</div>
  <div class="stars">★ ★ ★ ★ ★</div>
  {%- if site_url -%}
  <div class="footer-contact">{{ site_url }}{%- if phone -%} · {{ phone }}{%- endif -%}</div>
  {%- endif -%}
  <hr class="div-dash">

  {%- set branding_footer = "" -%}
  {%- if frappe.db.exists("DocType", "POS Branding Settings") -%}
    {%- set branding_doc = frappe.get_doc("POS Branding Settings") -%}
    {%- if branding_doc.enabled and branding_doc.receipt_footer -%}
      {%- set branding_footer = branding_doc.receipt_footer -%}
    {%- endif -%}
  {%- endif -%}
  {%- if branding_footer -%}
  <div style="font-size:8.5px;color:#555;margin:4px 0;">{{ branding_footer }}</div>
  {%- endif -%}

  <div class="receipt-id">{{ doc.name }} · POS Next · {{ doc.company }}</div>
</div>
